// Browser verification: drives the Glint UI end-to-end in real Chromium.
const { chromium } = require('/home/lane/rblx/node_modules/playwright');
const fs = require('fs');

const BASE = 'http://localhost:3001';
const SHOTS = '/tmp/glint-shots';
fs.mkdirSync(SHOTS, { recursive: true });

const suffix = Math.random().toString(36).slice(2, 6);
const ALICE = 'ui_alice_' + suffix;
const BOB = 'ui_bob_' + suffix;

let step = 0;
const log = (s) => console.log(s);
const shot = async (page, name) => {
  const p = `${SHOTS}/${String(++step).padStart(2, '0')}-${name}.png`;
  await page.screenshot({ path: p });
  return p;
};

async function signup(page, username) {
  await page.goto(BASE);
  await page.click('#tab-register');
  await page.fill('#auth-user', username);
  await page.fill('#auth-pass', 'test1234');
  await page.click('#auth-go');
  await page.waitForSelector('#topnav:not(.hidden)', { timeout: 8000 });
}

(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'],
  });
  const ctxA = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const ctxB = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const alice = await ctxA.newPage();
  const bob = await ctxB.newPage();
  const errors = [];
  for (const [p, who] of [[alice, 'alice'], [bob, 'bob']]) {
    p.on('pageerror', (e) => errors.push(`[${who}] pageerror: ${e.message}`));
    p.on('console', (m) => { if (m.type() === 'error') errors.push(`[${who}] console: ${m.text()}`); });
  }

  // ---- 1. signup + home ----
  await signup(alice, ALICE);
  await alice.waitForSelector('.hero');
  const officialCount = await alice.locator('.game-card').count();
  log(`✅ signup+home: hero rendered, ${officialCount} game cards visible`);
  log('   shot: ' + await shot(alice, 'home'));

  // ---- 2. game page ----
  await alice.click('.game-card:has-text("Tower of Bother")');
  await alice.waitForSelector('h1:has-text("Tower of Bother")');
  const cfgRows = await alice.locator('table.cfg tr').count();
  log(`✅ game page: title + config table (${cfgRows} rows)`);
  log('   shot: ' + await shot(alice, 'gamepage'));

  // ---- 3. play 3D game ----
  await alice.click('a.btn:has-text("Play")');
  await alice.waitForSelector('#game-root canvas');
  await alice.waitForFunction(() => {
    const el = document.querySelector('#hud-gamename');
    return el && el.textContent !== 'Connecting…';
  }, { timeout: 10000 });
  await alice.waitForTimeout(2500);
  const webgl = await alice.evaluate(() => {
    const c = document.querySelector('#game-root canvas');
    return !!(c && (c.getContext('webgl2') || c.getContext('webgl')));
  });
  const shotBefore = `${SHOTS}/__before-move.png`;
  await alice.screenshot({ path: shotBefore });
  log(`✅ play page: canvas live, WebGL context: ${webgl}`);

  // movement: hold W for 1.2s, compare pixels
  await alice.click('#game-root canvas', { position: { x: 640, y: 400 } });
  await alice.keyboard.down('w');
  await alice.waitForTimeout(1200);
  await alice.keyboard.up('w');
  await alice.waitForTimeout(400);
  const shotAfterP = await shot(alice, 'play-after-move');
  const b1 = fs.readFileSync(shotBefore), b2 = fs.readFileSync(shotAfterP);
  log(`${!b1.equals(b2) ? '✅' : '❌'} movement: frame changed after holding W (${b1.length}b vs ${b2.length}b)`);

  // ---- 4. second real player joins same lobby ----
  await signup(bob, BOB);
  await bob.goto(BASE + '/#' + new URL(alice.url()).hash.slice(1)); // same /play/<id>
  await bob.waitForSelector('#game-root canvas');
  await bob.waitForTimeout(2500);
  const lbBob = await bob.locator('#hud-lb .lb-row').count();
  const lbAlice = await alice.locator('#hud-lb .lb-row').count();
  log(`${lbBob === 2 && lbAlice === 2 ? '✅' : '❌'} multiplayer: leaderboard shows 2 players on both clients (alice=${lbAlice}, bob=${lbBob})`);
  const joinMsg = await alice.locator('#chat-log .sys').last().textContent();
  log(`✅ join broadcast: alice sees "${joinMsg}"`);

  // chat across clients
  await alice.click('#game-root canvas');
  await alice.keyboard.press('/');
  await alice.fill('#chat-input', 'hello from alice!');
  await alice.keyboard.press('Enter');
  await bob.waitForSelector('#chat-log div:has-text("hello from alice!")', { timeout: 5000 });
  log('✅ chat: bob received alice\'s message in-game');
  log('   shot(bob): ' + await shot(bob, 'bob-sees-alice'));
  log('   shot(alice): ' + await shot(alice, 'alice-ingame'));

  // leave game
  await alice.click('#hud-leave');
  await alice.waitForSelector('.game-head');
  await bob.click('#hud-leave');
  await bob.waitForSelector('.game-head');
  log('✅ leave: both returned to game page');

  // ---- 5. studio: create + place a part ----
  await alice.click('a[href="#/studio"]');
  await alice.waitForSelector('#new-name');
  await alice.fill('#new-name', 'UI Test World');
  await alice.click('#new-go');
  await alice.waitForSelector('#studio-canvas-wrap canvas', { timeout: 8000 });
  await alice.waitForSelector('#st-config #cfg-name');
  const studioUrl = alice.url();
  const gameId = studioUrl.match(/studio\/([\w-]+)/)[1];
  // place a kill brick: select from palette, hover canvas, click
  await alice.click('#st-palette button:has-text("Kill Brick")');
  await alice.mouse.move(640, 400);
  await alice.waitForTimeout(300);
  await alice.mouse.click(640, 400);
  await alice.waitForTimeout(600);
  const parts = await (await fetch(`${BASE}/api/games/${gameId}`, { headers: { cookie: (await ctxA.cookies()).map(c => `${c.name}=${c.value}`).join('; ') } })).json();
  log(`${parts.game.partCount === 3 ? '✅' : '❌'} studio place: part count ${parts.game.partCount} (baseplate+spawn+kill brick)`);
  log('   shot: ' + await shot(alice, 'studio'));

  // select the part -> properties panel
  await alice.click('button[data-tool="select"]');
  await alice.mouse.click(640, 400);
  await alice.waitForTimeout(300);
  const propsVisible = await alice.locator('#st-props input[data-prop="x"]').count();
  log(`${propsVisible ? '✅' : '❌'} studio select: properties panel shows position/size inputs`);

  // ---- 6. studio collaboration: bob joins live ----
  await alice.click('#st-exit');
  await alice.waitForSelector('#new-name');
  await alice.goto(BASE + '/#/game/' + gameId);
  await alice.waitForSelector('#collab-name');
  await alice.fill('#collab-name', BOB);
  await alice.click('#collab-add');
  await alice.waitForSelector(`#collab-list :text("${BOB}")`, { timeout: 5000 });
  log('✅ collaborators: bob added via game page UI');

  await alice.goto(BASE + '/#/studio/' + gameId);
  await alice.waitForSelector('#studio-canvas-wrap canvas');
  await bob.goto(BASE + '/#/studio/' + gameId);
  await bob.waitForSelector('#studio-canvas-wrap canvas');
  await alice.waitForSelector(`#st-editors .editor-chip:has-text("${BOB}")`, { timeout: 6000 });
  await bob.waitForSelector(`#st-editors .editor-chip:has-text("${ALICE}")`, { timeout: 6000 });
  log('✅ studio collab: both see each other\'s editor chips');

  // bob places a coin; alice's client should receive the op (verify via API after)
  await bob.click('#st-palette button:has-text("Coin")');
  await bob.mouse.move(500, 350);
  await bob.waitForTimeout(300);
  await bob.mouse.click(500, 350);
  await bob.waitForTimeout(700);
  const parts2 = await (await fetch(`${BASE}/api/games/${gameId}`, { headers: { cookie: (await ctxB.cookies()).map(c => `${c.name}=${c.value}`).join('; ') } })).json();
  log(`${parts2.game.partCount === 4 ? '✅' : '❌'} collab edit: bob's coin persisted (parts=${parts2.game.partCount})`);
  // alice sees it live: her world mesh count via studio chat as proxy — instead check team chat
  await bob.fill('#st-chat-input', 'placed a coin for you');
  await bob.press('#st-chat-input', 'Enter');
  await alice.waitForSelector('#studio-chat-log div:has-text("placed a coin")', { timeout: 5000 });
  log('✅ studio team chat: alice received bob\'s message');
  log('   shot(alice studio): ' + await shot(alice, 'studio-collab'));
  await alice.click('#st-exit');
  await bob.click('#st-exit');
  await alice.waitForSelector('#new-name');
  await bob.waitForSelector('#new-name');

  // ---- 7. avatar editor ----
  await alice.click('a[href="#/avatar"]');
  await alice.waitForSelector('.avatar-preview canvas');
  await alice.waitForTimeout(800);
  await alice.click('#av-body [data-c="#e54b4b"]');
  await alice.click('#av-save');
  await alice.waitForSelector('.toast:has-text("Avatar saved")', { timeout: 5000 });
  log('✅ avatar: torso recolored + saved (toast confirmed)');
  log('   shot: ' + await shot(alice, 'avatar'));

  // ---- 8. catalog purchase ----
  await alice.click('a[href="#/catalog"]');
  await alice.waitForSelector('.item-card');
  const glimBefore = await alice.locator('#nav-glimmers').textContent();
  await alice.click('.item-card:has-text("Traffic Cone") button[data-buy]');
  await alice.waitForSelector('.toast:has-text("Purchased")', { timeout: 5000 });
  const glimAfter = await alice.locator('#nav-glimmers').textContent();
  log(`✅ catalog: bought Traffic Cone (${glimBefore.trim()} → ${glimAfter.trim()}), nav balance updated`);
  const ownedBadge = await alice.locator('.item-card:has-text("Traffic Cone") .badge:has-text("OWNED")').count();
  log(`${ownedBadge ? '✅' : '❌'} catalog: card flips to OWNED`);
  log('   shot: ' + await shot(alice, 'catalog'));

  // ---- 9. friends flow through UI ----
  await alice.click('a[href="#/friends"]');
  await alice.waitForSelector('#fr-name');
  await alice.fill('#fr-name', BOB);
  await alice.click('#fr-add');
  await alice.waitForSelector('.toast:has-text("Request sent")');
  await bob.click('a[href="#/friends"]');
  await bob.waitForSelector(`.friend-row:has-text("${ALICE}") .btn:has-text("Accept")`);
  await bob.click(`.friend-row:has-text("${ALICE}") .btn:has-text("Accept")`);
  await bob.waitForSelector(`.panel .friend-row:has-text("${ALICE}")`);
  await alice.click('a[href="#/friends"]');
  await alice.waitForSelector(`.friend-row:has-text("${BOB}")`);
  const bobOnline = await alice.locator(`.friend-row:has-text("${BOB}") .presence-dot.on`).count();
  log(`✅ friends: request→accept via UI, bob listed${bobOnline ? ' (online)' : ''}`);
  log('   shot: ' + await shot(alice, 'friends'));

  // ---- 10. probes ----
  // probe: wrong password shows inline error
  const eve = await ctxA.browser().newContext({ viewport: { width: 1280, height: 800 } });
  const evePage = await eve.newPage();
  await evePage.goto(BASE);
  await evePage.fill('#auth-user', ALICE);
  await evePage.fill('#auth-pass', 'wrongpass');
  await evePage.click('#auth-go');
  await evePage.waitForSelector('#auth-err:has-text("Wrong username or password")');
  log('🔍 probe: bad login → inline "Wrong username or password"');

  // probe: signup with bad username shows validation error
  await evePage.click('#tab-register');
  await evePage.fill('#auth-user', 'x');
  await evePage.fill('#auth-pass', 'test1234');
  await evePage.click('#auth-go');
  await evePage.waitForSelector('#auth-err:has-text("3-20")');
  log('🔍 probe: 1-char username → validation message shown');

  // probe: garbage route
  await alice.goto(BASE + '/#/nonsense/route');
  await alice.waitForSelector('.empty-note:has-text("Page not found")');
  log('🔍 probe: unknown route → "Page not found", no crash');

  // probe: chat XSS attempt
  await alice.goto(BASE + '/#/play/' + gameId);
  await alice.waitForSelector('#chat-input');
  await alice.waitForTimeout(1500);
  await alice.fill('#chat-input', '<img src=x onerror=window.__xss=1>');
  await alice.press('#chat-input', 'Enter');
  await alice.waitForTimeout(600);
  const xss = await alice.evaluate(() => window.__xss);
  const chatShown = await alice.locator('#chat-log div:has-text("img src")').count();
  log(`${!xss && chatShown ? '✅' : '❌'} 🔍 probe: HTML in chat rendered as text, no script execution (xss=${xss})`);
  await alice.click('#hud-leave');

  log('\nConsole/page errors captured: ' + (errors.length ? '\n' + errors.join('\n') : 'none'));
  await browser.close();
})().catch((e) => { console.error('UI TEST CRASH:', e.message); process.exit(1); });
